* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  background: #f4f6f9;
  color: #333;
}

h1 {
  text-align: center;
  padding: 18px 0 8px;
  font-size: 1.6rem;
  color: #1a1a2e;
}

.container {
  display: flex;
  gap: 20px;
  padding: 10px 24px 24px;
  max-width: 1600px;
  margin: 0 auto;
  align-items: flex-start;
}

/* ---------- Bubble chart ---------- */
.chart-panel {
  flex: 1 1 55%;
  min-width: 0;
  background: #fff;
  border-radius: 10px;
  box-shadow: 0 2px 8px rgba(0,0,0,.1);
  padding: 14px;
}

.chart-panel h2 {
  font-size: 1.05rem;
  margin-bottom: 6px;
  color: #444;
  text-align: center;
}

#bubble-chart {
  width: 100%;
}

#bubble-chart svg {
  display: block;
  margin: 0 auto;
}

.bubble-label {
  pointer-events: none;
  font-size: 10px;
  font-weight: 600;
  fill: #fff;
  text-anchor: middle;
  dominant-baseline: central;
}

/* ---------- Tooltip ---------- */
.tooltip {
  position: absolute;
  pointer-events: none;
  background: rgba(30, 30, 50, .92);
  color: #fff;
  padding: 10px 14px;
  border-radius: 6px;
  font-size: 13px;
  line-height: 1.5;
  max-width: 280px;
  box-shadow: 0 4px 14px rgba(0,0,0,.25);
  opacity: 0;
  transition: opacity .15s;
  z-index: 100;
}

.tooltip .tt-ticker {
  font-weight: 700;
  font-size: 14px;
  margin-bottom: 2px;
}

.tooltip .tt-name {
  font-size: 12px;
  opacity: .85;
}

.tooltip .tt-sector {
  font-size: 12px;
  margin-top: 4px;
  color: #a8d8ff;
}

/* ---------- Legend ---------- */
.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 16px;
  justify-content: center;
  margin-top: 10px;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 12px;
  color: #555;
}

.legend-swatch {
  width: 14px;
  height: 14px;
  border-radius: 3px;
  flex-shrink: 0;
}

/* ---------- Table panel ---------- */
.table-panel {
  flex: 1 1 45%;
  min-width: 0;
  background: #fff;
  border-radius: 10px;
  box-shadow: 0 2px 8px rgba(0,0,0,.1);
  padding: 14px;
  max-height: 700px;
  display: flex;
  flex-direction: column;
}

.table-panel h2 {
  font-size: 1.05rem;
  margin-bottom: 6px;
  color: #444;
  text-align: center;
}

.table-wrapper {
  overflow-y: auto;
  flex: 1;
}

#stock-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

#stock-table thead {
  position: sticky;
  top: 0;
  z-index: 2;
}

#stock-table th {
  background: #2c3e6b;
  color: #fff;
  padding: 9px 10px;
  text-align: left;
  font-weight: 600;
  white-space: nowrap;
}

#stock-table td {
  padding: 7px 10px;
  border-bottom: 1px solid #e8eaed;
  white-space: nowrap;
}

#stock-table tbody tr {
  cursor: pointer;
  transition: background .12s;
}

#stock-table tbody tr:hover {
  background: #eef3fb;
}

#stock-table tbody tr.selected {
  background: #cde0f7;
}

/* Bubble highlight */
circle.bubble-selected {
  stroke: #ff6600;
  stroke-width: 3px;
}

