// ============================================================
// Stock Visualization - Bubble Chart + Data Table
// ============================================================

(function () {
  "use strict";

  // ---- colour palette per sector ----
  const sectorColors = {
    "Information Technology": "#4285F4",
    "Industry":              "#34A853",
    "Energy":                "#FBBC05",
    "Financial":             "#EA4335",
    "ETF":                   "#8E44AD"
  };

  const colorOf = (sector) => sectorColors[sector] || "#999";

  // ---- Format market cap ----
  function fmtCap(v) {
    if (v == null || v === "" || isNaN(+v)) return "\u2014";
    v = +v;
    if (v >= 1e12) return (v / 1e12).toFixed(2) + "T";
    if (v >= 1e9)  return (v / 1e9).toFixed(2) + "B";
    if (v >= 1e6)  return (v / 1e6).toFixed(2) + "M";
    return v.toLocaleString();
  }

  // ---- Load CSV ----
  d3.csv("data/stock-descriptions.csv").then(function (raw) {
    const data = raw.map(function (d) {
      return {
        ticker:    d.ticker,
        name:      d["full name"],
        sector:    d.sector,
        marketCap: d.marketCap === "" ? null : +d.marketCap,
        country:   d.country || null,
        website:   d.website || null
      };
    });

    drawBubbleChart(data);
    drawTable(data);
  });

  // ============================
  //  Bubble Chart
  // ============================
  function drawBubbleChart(data) {
    const width  = 700;
    const height = 620;

    const svg = d3.select("#bubble-chart")
      .append("svg")
      .attr("viewBox", [0, 0, width, height])
      .attr("width", width)
      .attr("height", height);

    // ----- radius scale (sqrt so area ~ marketCap) -----
    const caps = data.filter(d => d.marketCap != null).map(d => d.marketCap);
    const rScale = d3.scaleSqrt()
      .domain([d3.min(caps), d3.max(caps)])
      .range([12, 52]);

    const etfRadius = 14;                       // uniform for ETFs

    function radius(d) {
      return d.marketCap != null ? rScale(d.marketCap) : etfRadius;
    }

    // ----- sector centres for clustering -----
    const sectors = Object.keys(sectorColors);
    const sectorCenter = {};

    // Lay out sectors in a roughly centered pattern
    const cx = width / 2;
    const cy = height / 2;
    const positions = [
      { x: cx - 140, y: cy - 120 },   // Info Tech (top-left)
      { x: cx + 160, y: cy - 120 },   // Industry  (top-right)
      { x: cx - 140, y: cy + 100 },   // Energy    (bottom-left)
      { x: cx + 160, y: cy + 100 },   // Financial (bottom-right)
      { x: cx,       y: cy       }    // ETF       (centre)
    ];

    sectors.forEach(function (s, i) {
      sectorCenter[s] = positions[i] || { x: cx, y: cy };
    });

    // ----- nodes -----
    const nodes = data.map(function (d) {
      var sc = sectorCenter[d.sector] || { x: cx, y: cy };
      return {
        ...d,
        r: radius(d),
        x: sc.x + (Math.random() - 0.5) * 60,
        y: sc.y + (Math.random() - 0.5) * 60
      };
    });

    // ----- force simulation -----
    const simulation = d3.forceSimulation(nodes)
      .force("x", d3.forceX(function (d) { return (sectorCenter[d.sector] || { x: cx }).x; }).strength(0.35))
      .force("y", d3.forceY(function (d) { return (sectorCenter[d.sector] || { y: cy }).y; }).strength(0.35))
      .force("collide", d3.forceCollide(function (d) { return d.r + 2; }).iterations(4))
      .force("charge", d3.forceManyBody().strength(-5))
      .stop();

    // Run simulation synchronously
    for (var i = 0; i < 300; i++) simulation.tick();

    // ----- draw bubbles -----
    const g = svg.append("g");

    const bubbles = g.selectAll("g.bubble")
      .data(nodes)
      .join("g")
      .attr("class", "bubble")
      .attr("transform", function (d) { return "translate(" + d.x + "," + d.y + ")"; });

    bubbles.append("circle")
      .attr("r", function (d) { return d.r; })
      .attr("fill", function (d) { return colorOf(d.sector); })
      .attr("fill-opacity", 0.85)
      .attr("stroke", function (d) { return d3.color(colorOf(d.sector)).darker(0.5); })
      .attr("stroke-width", 1.2);

    bubbles.append("text")
      .attr("class", "bubble-label")
      .text(function (d) { return d.ticker; })
      .style("font-size", function (d) {
        return Math.max(8, Math.min(d.r * 0.55, 14)) + "px";
      });

    // ----- tooltip -----
    const tip = d3.select(".tooltip");

    bubbles
      .on("mouseenter", function (event, d) {
        if (d.sector === "ETF") return;          // no tooltip for ETFs
        tip.style("opacity", 1)
          .html(
            '<div class="tt-ticker">' + d.ticker + '</div>' +
            '<div class="tt-name">' + d.name + '</div>' +
            '<div class="tt-sector">Sector: ' + d.sector + '</div>'
          );
      })
      .on("mousemove", function (event) {
        tip.style("left", (event.pageX + 14) + "px")
           .style("top",  (event.pageY - 28) + "px");
      })
      .on("mouseleave", function () {
        tip.style("opacity", 0);
      });

    // ----- click selection (linked with table) -----
    bubbles.on("click", function (event, d) {
      selectStock(d.ticker);
    });

    // expose for table -> bubble link
    window._bubbles = bubbles;

    // ----- legend -----
    const legend = d3.select("#bubble-legend");
    sectors.forEach(function (s) {
      var item = legend.append("div").attr("class", "legend-item");
      item.append("span")
        .attr("class", "legend-swatch")
        .style("background", sectorColors[s]);
      item.append("span").text(s);
    });
  }

  // ============================
  //  Data Table
  // ============================
  function drawTable(data) {
    const thead = d3.select("#stock-table thead tr");
    const columns = [
      { label: "Ticker",    key: "ticker" },
      { label: "Company",   key: "name" },
      { label: "Sector",    key: "sector" },
      { label: "Market Cap",key: "marketCap" }
    ];

    thead.selectAll("th")
      .data(columns)
      .join("th")
      .text(function (c) { return c.label; });

    const tbody = d3.select("#stock-table tbody");
    const rows = tbody.selectAll("tr")
      .data(data)
      .join("tr")
      .attr("data-ticker", function (d) { return d.ticker; });

    rows.selectAll("td")
      .data(function (d) {
        return columns.map(function (c) {
          if (c.key === "marketCap") return fmtCap(d.marketCap);
          return d[c.key];
        });
      })
      .join("td")
      .text(function (v) { return v; });

    rows.on("click", function (event, d) {
      selectStock(d.ticker);
    });

    window._tableRows = rows;
  }

  // ============================
  //  Linked selection
  // ============================
  var currentTicker = null;

  function selectStock(ticker) {
    // Toggle if clicking same stock
    if (currentTicker === ticker) {
      currentTicker = null;
    } else {
      currentTicker = ticker;
    }

    // highlight bubble
    if (window._bubbles) {
      window._bubbles.select("circle")
        .classed("bubble-selected", function (d) { return d.ticker === currentTicker; });
    }

    // highlight table row & scroll into view
    if (window._tableRows) {
      window._tableRows.classed("selected", function (d) { return d.ticker === currentTicker; });

      if (currentTicker) {
        var row = document.querySelector('#stock-table tbody tr[data-ticker="' + currentTicker + '"]');
        if (row) {
          row.scrollIntoView({ behavior: "smooth", block: "center" });
        }
      }
    }
  }

})();

